def g_cycle():
    o=T(170,12,'командалық цикл (1 команда)','t-s mu')
    o+='<rect x="10" y="18" width="320" height="26" rx="6" class="bxa"/>'+T(170,35,'алу → декодтау → орындау → жазу','t-s')
    o+=T(170,62,'3 машиналық цикл (мысал үшін)','t-s mu')
    for i,l in enumerate(('команданы алу','деректі оқу','нәтижені жазу')):o+=B(10+i*107,68,106,30,l,'bx','t-s')
    o+=T(170,116,'әрқайсысы 4 такт, барлығы 12 такт','t-s mu')
    for i in range(12):
        x=10+i*26.67
        o+=f'<rect x="{x:.1f}" y="122" width="25" height="24" rx="3" class="bx"/>'+T(round(x+12.5,1),138,str(i+1),'t-s')
    o+=T(170,170,'2 МГц-те бір такт 0,5 мкс, команда 6 мкс','t-s ac')
    return o
