def g_pipe():
    st=['IF','ID','EX','MEM','WB'];x0=48;cw=34
    o=TL(6,12,'такт','t-s mu')
    for c in range(8):o+=T(x0+c*cw+cw/2,12,str(c+1),'t-s mu')
    for i in range(4):
        y=20+i*30;o+=TL(6,y+17,f'К{i+1}','t-s t-b')
        for s,l in enumerate(st):o+=B(x0+(i+s)*cw+1,y,cw-2,24,l,'bxa' if s==4 else 'bx','t-s',r=4)
