def g_haz():
    x0=96;cw=26
    o=TL(4,12,'такт','t-s mu')
    for c in range(9):o+=T(x0+c*cw+cw/2,12,str(c+1),'t-s mu')
    def row(y,label,cells):
        r=TL(4,y+17,label,'t-s t-b')
        for col,l,cl in cells:r+=B(x0+(col-1)*cw+1,y,cw-2,24,l,cl,'t-s' if cl!='soft' else 't-s mu',r=4)
        return r
    o+=row(20,'ADD',[(1,'IF','bx'),(2,'ID','bx'),(3,'EX','bxa'),(4,'MEM','bx'),(5,'WB','bx')])
    o+=row(52,'SUB (тікелей)',[(2,'IF','bx'),(3,'ID','bx'),(4,'EX','bxa'),(5,'MEM','bx'),(6,'WB','bx')])
    o+=A(161,44,185,53,'lna','hda')
    o+=row(84,'SUB (күту)',[(2,'IF','bx'),(3,'—','soft'),(4,'—','soft'),(5,'—','soft'),(6,'ID','bx'),(7,'EX','bx'),(8,'MEM','bx'),(9,'WB','bx')])
    o+=T(170,122,'тікелей беру: 0 тоқтау · күту: 3 такт тоқтау','t-s ac')
    return o
f_haz=F(S(340,130,g_haz(),'ADD нәтижесін SUB күтеді немесе тікелей алады'),'ADD нәтижесі 3-тактіде (EX) дайын. Тікелей беру оны SUB-тың EX кезеңіне өткізеді. Әйтпесе SUB 3 такт күтеді («—»)')

