def g_smt():
    o=''
    for x0,title,cells,txt in ((10,'бір ағын',[(t,s,'A') for t,s in SA],'6 / 24 слот'),(178,'SMT: екі ағын',[(t,s,'A') for t,s in SA]+[(t,s,'B') for t,s in SB],'18 / 24 слот')):
        o+=T(x0+66,14,title,'t-s t-b')
        d={(t,s):k for t,s,k in cells}
        for t in range(6):
            for s in range(4):
                k=d.get((t,s));x=x0+t*22;y=24+s*22
                o+=f'<rect x="{x}" y="{y}" width="20" height="20" rx="3" class="{"bxa" if k=="A" else "bx" if k=="B" else "soft"}"/>'
                if k:o+=T(x+10,y+14,'А' if k=='A' else 'Б','t-s')
        o+=T(x0+66,126,txt,'t-s ac')
    return o
