    o=T(137,12,'бір дерек','t-s mu')+T(263,12,'көп дерек','t-s mu')
    cells=[(76,22,'SISD',['бір ядролы МП']),(202,22,'SIMD',['AVX, NEON, GPU']),(76,88,'MISD',['сирек:','қателікке төзімді']),(202,88,'MIMD',['көпядролы МП,','мультипроцессор'])]
